using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.StatisticalMechanics.CellularAutomata;

internal sealed class KleinFourFactorizationDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/StatisticalMechanics/CellularAutomata/KleinFourFactorization.";
    private static readonly LibraryNoteRef Source =
        LibraryNoteRef.Create("D5/L/StatisticalMechanics/alcalaarroyo2026kleinfour");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Let H = Multiplicative(ZMod(2) x ZMod(2)), with alphabet Bool. Configurations are all functions H -> Bool, and the right shift is rho_g(x)(h) = x(h g). The predicates IsCA, IsLazy and IsInvertibleCA are the existing local-rule predicates: a lazy rule has exactly one active exceptional pattern on any finite neighborhood containing 1. Let W_n be the set of configurations with exactly n true cells, C the two constants, O(x) the shift orbit of x, and c_b the constant with value b. Write w_false = 1 and w_true = 3. The public theorem below transports the structural proof by E. Alcala-Arroyo, A. Castillo-Ramirez, H. Ma and W. Zhang (public supplement v1.1.0, DOI 10.5281/zenodo.23280244) to this configuration space.",
        H("Membership in the lazy and invertible generated submonoid"),
        Blocks(Describe.Lean(DescribeId.Create("kleinfour-actual-membership"),
            DeclarationHandle.Create(Prefix + "membership_iff"),
            H("The structural criterion on actual configurations"),
            StatementSource.FromAuthor(Disp(Statement())),
            AssessedProvenance.FromRepo(Source),
            Blocks(Paragraph(Text("U comprises all maps satisfying IsInvertibleCA and L all maps satisfying IsLazy. The generated submonoid includes the identity, represented by the empty word. A common image W_(w_b) in the antecedent is a free orbit; images that are constant or two-point orbits do not activate this condition. The consequent states equality of the image of C union O(x) with the singleton {c_b}, where O(x) has two points.")),
                Paragraph(Text("The 16-point representation, partitioned into seven orbits, is bijective with all configurations. Sending false and true to 0 and 1 in each group coordinate identifies xor with multiplication in H and carries the model action to the right shift. Conjugation identifies every model equivariant map with a cellular automaton; conversely every cellular automaton commutes with shifts and gives a model equivariant map. On this finite group every equivariant map has a full-neighborhood local rule. The lazy generators correspond in both directions by transporting the neighborhood and exceptional pattern, extending that pattern arbitrarily outside its neighborhood. Bijectivity gives an equivariant inverse and hence agrees with IsInvertibleCA. These identities transport both inclusions of the generated closure.")),
                Paragraph(Text("For the reverse implication, a nonmerging map factors into elementary collapses, independent lower-stratum actions and a unit extending the partial permutation on the free strata. A merging map with the stated witness factors through B_s, followed and preceded by nonmerging maps. With k_s the nonidentity group element selected by the index s, the transported coordinate rule is B_s(x)(g) = x(g) and not x(g k_s). Every factor belongs to the full lawful generating family. Weight-one and weight-three configurations are exactly the two model free strata, and the three model pair strata exhaust all two-point shift orbits. This native theorem asserts the structural membership criterion. The following sections give the separately attributed source-backed count arguments and their native limits."))),
            DescribeRole.Theorem),
            new DocumentBlock.Section(H("The two counts and their source scope"), Blocks(
                Paragraph(Text("The following is a mathematical exposition of the two counts in the public supplement by Edgar Alcalá-Arroyo, Alonso Castillo-Ramirez, Haobo Ma and Wenlin Zhang, version v1.1.0, DOI 10.5281/zenodo.23280244, commit fae47ad9dbbd4cbc1462a058dffe6ad4c2e416f1. Its endpoints are KleinFour.membership_card in KleinFour/Count.lean and KleinFour.lazy_membership_card in KleinFour/LazyFinal.lean. The structural theorem above is the adopted native result. The count arguments below are source-backed analysis; they do not add count declarations or inherit that theorem's native verification badge. The full MIT notice for this adaptation is retained in the accompanying Library entry.")),
                Paragraph(Text("Put Q = H → Bool and E = Function.End Q. Multiplication is right-to-left composition: (A * B)(x) = A(B(x)); equality is equality of functions on all configurations. Write U = {T ∈ E : IsInvertibleCA T} and L_H = {T ∈ E : IsLazy T}. The two conclusions are Nat.card(Submonoid.closure(U ∪ L_H)) = 59712 and Nat.card(Submonoid.closure L_H) = 4007. These count distinct transformations of Q, not words, generator descriptions or orbit classes.")),
                Paragraph(Text("For precision, IsCA(T) means that some finite S ⊆ H and μ : (S → Bool) → Bool satisfy T(x)(g) = μ(s ↦ x(sg)). IsLazy(T) requires 1 ∈ S and one pattern p : S → Bool with μ(z) = z(1) if and only if z ≠ p. Since the alphabet is binary, the output at a match is the complement of the central bit: T(x)(g) = ¬x(g) when every s ∈ S satisfies x(sg) = p(s), and T(x)(g) = x(g) otherwise. Every such neighborhood and every such pattern is included. An extension of p outside S has no effect. IsInvertibleCA(T) requires T and a two-sided inverse to be CAs. Both closures contain the identity, the empty word. The identity itself is not lazy: extend the exceptional pattern to a configuration and its value at 1 changes. No shortest-word assertion is needed."))
            )),
            new DocumentBlock.Section(H("All sixteen configurations and both table inverses"), Blocks(
                Paragraph(Text("Use G = Bool × Bool with coordinatewise xor ⊕ and e = (0,0). Its three nonzero characters χ_s, for s = 0,1,2, are the first coordinate, second coordinate and their xor. The model X has points c_b, p_(s,b) and f_(b,g), with b ∈ Bool and g ∈ G. Encode them respectively as the functions h ↦ b, h ↦ b ⊕ χ_s(h), and h ↦ b ⊕ [h = g]. There are two constants, six pair points and eight free points. Every two-element subset {u,v} of G is the coset u + {e,u ⊕ v} of a unique order-two subgroup, so its indicator is a unique p_(s,b). Every odd-weight configuration has a unique minority position g and is a unique f_(b,g). Constants have weights zero or four. Thus these disjoint cases exhaust all 16 functions G → Bool, with a unique inverse decode. In particular decode(encode(x)) = x and encode(decode(z)) = z. X records all points in the seven orbits, not their quotient.")),
                Paragraph(Text("Translation by g fixes c_b, sends p_(s,b) to p_(s,b ⊕ χ_s(g)), and sends f_(b,h) to f_(b,h ⊕ g). Call this action act_g. Its encoding is the right shift: encode(act_g x)(h) = encode(x)(h ⊕ g). The stabilizers are G for constants, ker χ_s for pair s, and {e} for free points. Equivariant maps cannot decrease stabilizers. The points fixed by all of G are precisely the constants, and those fixed by ker χ_s are precisely the constants and the two points of pair s.")),
                Paragraph(Text("Consequently an equivariant transformation has a table t = (c,d,y), where c : Bool → Bool, d : Fin 3 → Bool × Bool, and y : Bool → X. If d_s = (r,a), its action is T_t(c_b) = c_(c(b)); T_t(p_(s,b)) = p_(s,a ⊕ b) when r = true and c_a when r = false; and T_t(f_(b,g)) = act_g(y_b). Each such table is equivariant, because the pair formula respects χ_s and the free formula respects addition. Conversely, evaluate an equivariant T at c_b, p_(s,0) and f_(b,e). The stabilizer restrictions recover c(b), the unique descriptor d_s, and y_b. Equivariance then determines every remaining value.")),
                Paragraph(Text("Both inverse laws matter. Reconstructing after evaluation gives T_(tableOf T) = T: the constant case is immediate, the other pair point is a translate of p_(s,0), and every free point is a translate of f_(b,e). Evaluating a reconstructed table gives tableOf(T_t) = t: the constant bit is recovered, smallRun_pairValue recovers d_s from the image of p_(s,0), and act_e(y_b) = y_b recovers the free images. Hence tables are in bijection with actual equivariant functions, not merely representative-image classes. In supplier Tables.lean these laws are ca_tableOf and tableOf_ca; the adopted Invariant owner contains ca_tableOf and the representative identities used by the reverse calculation.")),
                Paragraph(Text("Write Lower = (Bool → Bool) × (Fin 3 → Bool × Bool) and Free = Bool → X. The table decomposition is a bijection with Lower × Free, with inverse assembling the two fields. Thus |Lower| = 2² · 4³ = 256, |Free| = 16² = 256, and the full CA monoid has 65536 elements. Finiteness and the ambient count follow from the bijections, rather than being assumptions about a table list."))
            )),
            new DocumentBlock.Section(H("Why the structural criterion is sufficient and necessary"), Blocks(
                Paragraph(Text("In the model let ICA be all equivariant bijections, L all lazyMap(S,p) with e ∈ S, and M = closure(ICA ∪ L). Merges(T) means that both free source orbits have the same free target orbit. Witness(T) means that for some s and a, T sends c_0, c_1, p_(s,0) and p_(s,1) all to c_a. The adopted Invariant and Factorization owners prove T ∈ M if and only if Merges(T) implies Witness(T). The following explains the ingredients reused in the count.")),
                Paragraph(Text("For necessity, a bijection cannot merge two disjoint free orbits: equivariance maps a free orbit with free image bijectively onto that image. A lazy rule with a nonconstant exceptional pattern has at most one occurrence on an odd-weight input, since a prescribed minority bit fixes the translation of its unique minority position. If the rule acts, it flips one cell and the output has even weight. Thus an odd output is unchanged, and no merger occurs. For a constant exceptional pattern, a one-cell neighborhood gives a constant output; a two-cell neighborhood {e,k} collapses both constants and the pair fixed by k to the opposite constant whenever a merger occurs; a three-cell neighborhood changes an affected odd input into an even one; a four-cell neighborhood leaves odd inputs unchanged. These cases include both constant symbols and all lawful neighborhoods, and prove the implication for every lazy generator.")),
                Paragraph(Text("Nonfree points never acquire free images, by their stabilizers. If A * B merges, the images under B of the two free representatives must therefore lie in free orbits. If their orbit labels agree, B merges and its witness survives postcomposition by A, since A maps constants to constants. If their labels differ, they exhaust the two free orbits and A merges; its witness survives precomposition by B, since B maps pair s only into constants or pair s. The identity satisfies the implication. Closure under composition proves necessity for every finite word, including the empty word.")),
                Paragraph(Text("For sufficiency, the units act independently as c_b ↦ c_(b ⊕ cflip), p_(s,b) ↦ p_(s,b ⊕ pflip_s), and f_(b,g) ↦ f_(b ⊕ swap,g ⊕ o_b). Their inverses use the same flips and the offset o_(b ⊕ swap), as unit_left and unit_right verify. ConstantCollapse(a) sends both constants to c_a and fixes all other points; PairCollapse(s,a) collapses pair s to c_a and fixes the other points. They are the full-neighborhood lazy maps with patterns encode(c_(¬a)) and encode(p_(s,¬a)). FreeCollapse(j,z) sends f_(j,g) to act_g(z) and fixes every other orbit.")),
                Paragraph(Text("The free-to-lower collapses have explicit unit conjugations. In the notation unit(cflip,pflip,swap,o), put u = unit(a,0,j,0). Then FreeCollapse(j,c_a) = u * lazyMap(G,encode(f_(0,e))) * u⁻¹. Let k_s be the nonidentity element of ker χ_s, and put v = unit(0,(t ↦ if t = s then ¬a else 0),j,(b ↦ k_s)). Then FreeCollapse(j,p_(s,a)) = v * lazyMap(G,encode(f_(0,k_s))) * v⁻¹. Evaluating on constants, each pair and each free point gives these equalities; they are the adopted freeToConstant_factor and freeToPair_factor. Every factor is an actual unit or lawful lazy map.")),
                Paragraph(Text("For any lower table l, first perform its constant action C, using either a constant collapse or a constant flip; next perform its independent pair actions P_0, P_1, P_2, each a pair flip or pair collapse. These pair operations fix constants, so lowerMap(l) = P_2 * P_1 * P_0 * C, with the rightmost factor applied first. For a nonmerging free table y, its surviving free images specify an injective partial permutation of the two free labels. Extend that to a permutation and choose the offsets of a unit N to match the surviving images. For nonsurviving images choose zero offset and then use the appropriate FreeCollapse into the lower stratum. These residual collapses fix every lower point and the other free orbit. Therefore T_t = residual_1 * residual_0 * lowerMap(l) * N. The construction covers zero, one or two surviving free orbits and proves every nonmerging map lies in M.")),
                Paragraph(Text("For a merging table write y_b = f_(q,h_b) and choose a witness pair s and constant a. Let B_s be the lazy map with neighborhood {e,k_s} and constant-true exceptional pattern. Its coordinate rule is x(g) ∧ ¬x(gk_s). It sends both constants and pair s to c_0, fixes the other pair points, and sends f_(b,g) to f_(0,g ⊕ b k_s), where b k_s is e for b = 0 and k_s for b = 1. Let α fix all lower points and translate free orbit b by h_b ⊕ b k_s. Let R have the required lower table and free action f_(b,g) ↦ f_(b ⊕ q,g). Then T_t = R * B_s * α: the two b k_s offsets cancel on free points; on the collapsed lower points equality follows from the witness; all other lower points pass unchanged through B_s and α. R is nonmerging and α is a unit. This proves sufficiency using the existing structural factorization, without enumerating words."))
            )),
            new DocumentBlock.Section(H("The mixed count 59712 by a disjoint partition"), Blocks(
                Paragraph(Text("A free table merges exactly when its two entries have the form y_0 = f_(q,h_0), y_1 = f_(q,h_1). The parameters q,h_0,h_1 are uniquely recovered from the entries, so there are 2 · 4 · 4 = 32 merging free tables and 16² − 32 = 224 nonmerging ones. A lower table has a witness exactly when c(0) = c(1) = a and at least one d_s equals (false,a). For a fixed a, there are 4³ possible pair descriptors and 3³ that avoid (false,a) at every s. The two choices of a are disjoint. Hence the number of witness lower tables is 2(4³ − 3³) = 74. Counting the complement prevents overcounting a table with two or three witness pairs.")),
                Paragraph(Text("Let GoodTable consist of the tables satisfying the criterion. Split a good table according to whether its free part merges. The nonmerging branch gives an arbitrary Lower together with a nonmerging Free; the merging branch gives a witness Lower together with a merging Free. Conversely, assemble the fields in either branch: the first satisfies the implication vacuously and the second by its witness. Splitting and assembling are inverse because merging and nonmerging are disjoint. Thus GoodTable is in bijection with (Lower × Free_nonmerge) disjoint-union (Lower_witness × Free_merge). The membership criterion and both table inverse laws identify M with GoodTable. Consequently |M| = 256 · 224 + 74 · 32 = 57344 + 2368 = 59712.")),
                Paragraph(Text("This is the analytic explanation of the partition goodParts and the cardinality proof membersToTables → good_table_card → membership_card in the pinned supplier Count.lean. The supplier discharges the three small finite counts with decide; the argument here explains the factors directly. A count of orbit labels alone would lose the h_0,h_1 choices and would not prove this statement."))
            )),
            new DocumentBlock.Section(H("The complete lazy family and the published 4007 certificate"), Blocks(
                Paragraph(Text("Now D = closure L in the full model CA monoid. A lawful neighborhood-pattern description chooses the central bit in two ways and, at each of the other three cells, chooses absent, prescribed-zero or prescribed-one. Hence there are 2 · 3³ = 54 descriptions. They induce distinct rules: the set of inputs changed at e is the nonempty cylinder specified by the pattern, and that cylinder recovers exactly the constrained coordinates and their values. More importantly for the certificate proof, supplier LazyFamilies.generators_checked proves all 54 listed generators lawful, and lazy_covered_check quantifies over every S : Finset G and every p : G → Bool with e ∈ S. Together generator_in_L and lazy_covered establish L = range(g ↦ a_g), including all extensions of neighborhood patterns. The count proof does not assume generator-list injectivity.")),
                Paragraph(Text("The immutable supplier data are in KleinFour/LazyData.lean. Define t_i = unpack(codesAt(i)) and m_i = T_(t_i) for i ∈ Fin 4007; define a_g = T_(unpack(generatorCodes[g])) for g ∈ Fin 54. A packed table stores the two constant bits in positions 0–1, the value and preserve/collapse bits of pair s in positions 2+2s and 3+2s, and the four-bit encodings of its two free images in positions 8–11 and 12–15. Unpack reverses those field operations using decode. The candidate count 4007 is only an index bound at this stage; it is not an assumed cardinality of D.")),
                Paragraph(Text("The lookup function is searchFind(pack(t)) modulo 4007. Similarly parent(i) = parentsAt(i) modulo 4007 and last(i) = lastGeneratorAt(i) modulo 54. These moduli and the arrays' default values ensure bounded indices, but prove neither a successful search nor any required equality. Those facts are certified separately. No sortedness assumption about a search tree, CSV total, breadth-first-search trace or assumed completeness enters the deduction.")),
                Paragraph(Text("Table composition is computed in the actual order A after B. Constant entries compose as c_A(c_B(b)). If B collapses pair s to c_b, the composite descriptor is (false,c_A(b)); if B preserves that pair, its xor offset is fed into A's pair action, which either preserves the pair with the combined offset or collapses it. The free entry is A.run(B.free(b)). LazyBoolean.compose_ca proves T_(compose(a,b)) = T_a * T_b. The Boolean comparison tableEqb compares all two constant entries, three pair descriptors and two free images. tableEqb_agrees and LazyFamilies.agrees_eq turn a true comparison into actual table equality, and therefore into function equality by the table representation.")),
                Paragraph(Text("The certificate obligations are: (i) m_0 = 1; (ii) for every i > 0, parent(i) < i and m_i = a_last(i) * m_parent(i); (iii) for every i, lookup(tableOf(m_i)) = i; (iv) for every i and every g, a_g * m_i = m_lookup(compose(unpack(generatorCodes[g]),t_i)). ParentCertificate is the universal conjunction parentBoolean(i) = true and indexBoolean(i) = true. The first Boolean tests strict parent descent and the composition equation when i ≠ 0; the second tests the lookup index. EdgeCertificate is the universal assertion booleanEdge(i,g) = true, whose comparison checks (iv). The root equation is root_check. None of these obligations assumes the desired count.")),
                Paragraph(Text("All 63 files KleinFour/LazyBlocks/Block00.lean through Block62.lean prove their CheckBlock(b) by unfolding CheckBlock and applying constructor followed by decide. Each block checks both parent/index facts and every one of the 54 generator edges at all 64 offsets r, using blockIndex(b,r) = (64b+r) modulo 4007. LazyEdges.all_blocks assembles the 63 proofs. For every i < 4007, take b = i div 64 < 63 and r = i mod 64 < 64; block_index proves that this recovers i. The last block covers 3968 through 4006 and then repeats 0 through 24. Thus every index and every generator edge is covered, including the tail. The Fin 8 sample checks elsewhere in the source do not supply the universal certificate and are not used to deduce the cardinality.")),
                Paragraph(Text("To prove reachability, use strong induction on i. At i = 0 the root is the identity, which lies in D. Otherwise the strict parent index supplies the induction hypothesis, a_last(i) is lawful, and the parent equation puts m_i in D. This proves range(m) ⊆ D without assuming any numerical size. To prove the reverse inclusion, use closure induction with the stronger statement that for every i there is j with T * m_i = m_j. For a generator, coverage L = range(a) and the edge equation give j. For the identity choose j = i. For A * B, first apply the assertion for B to i, then for A to the resulting index; associativity gives the assertion for the product. Finally set i = 0 and use m_0 = 1 to obtain T = m_j. Thus D ⊆ range(m).")),
                Paragraph(Text("If m_i = m_j, applying lookup after tableOf and using the two index equations gives i = j. Therefore i ↦ (m_i, its reachability proof) is a bijection Fin 4007 ≃ D. Cardinality invariance under this bijection gives Nat.card D = 4007. This is LazyReachable.enumeration and card_if_certificate. The final supplier theorem LazyFinal.lazy_membership_card supplies both all_parent_indices and all_boolean_edges, so the published result has no certificate hypotheses. The mathematical deduction uses the complete published checks, rather than treating conditional card_if_certificate alone as an unconditional theorem."))
            )),
            new DocumentBlock.Section(H("Transport of both counts to actual functions on Q"), Blocks(
                Paragraph(Text("Let φ : G ≃ H send Boolean coordinates to 0 or 1 in ZMod 2. It preserves e and multiplication: φ(e) = 1 and φ(g ⊕ h) = φ(g)φ(h). Define q : X ≃ Q by q(x)(h) = encode(x)(φ⁻¹(h)); its inverse sends z to decode(g ↦ z(φ(g))). The two encoding inverse laws and the two φ inverse laws give both q inverse laws. Moreover q(act_g x) = ρ_(φ(g))(q(x)). Consequently Lift(T) = q ∘ T ∘ q⁻¹ is an injective monoid homomorphism into Function.End Q, preserving the identity and right-to-left composition.")),
                Paragraph(Text("Every local-rule CA commutes with the right shifts by associativity. Conversely, if F commutes with shifts, choose the full neighborhood H and local rule μ(z) = F(z)(1). Then μ(s ↦ x(sg)) = F(ρ_g x)(1) = F(x)(g). Hence every such F is a CA and pulls back to q⁻¹ ∘ F ∘ q; lift_pull recovers F. The current owner's actual_equiv_iff, lift, lift_injective, pull and lift_pull establish these statements for the actual Q domain.")),
                Paragraph(Text("Transport a lazy neighborhood by φ and its pattern by precomposition with φ⁻¹. Membership of the identity is preserved, and the matching condition becomes x(φ(s)g) = p(s), exactly the actual local rule. Transport back by φ⁻¹ for the converse, extending a restricted pattern arbitrarily outside its neighborhood. Thus Lift maps precisely L onto L_H, not just a selected list of patterns. A model bijection transports to an actual bijection; its inverse is equivariant because applying the bijection to the desired commutation equation reduces it to the original equivariance. By the full-neighborhood argument that inverse is also a CA. The current lazy_lift_iff and invertible_lift_iff therefore identify the two full generating families.")),
                Paragraph(Text("For the mixed monoid, lift_mem_generated gives inclusion in closure(U ∪ L_H), and generated_representation supplies every element of that closure as Lift(T) with T ∈ M. Injectivity of Lift gives a bijection M ≃ closure(U ∪ L_H). For the lazy-only monoid, Lift(L) = L_H implies (closure L).map(Lift) = closure L_H by MonoidHom.map_mclosure, or directly by induction on words in both directions. Restrict Lift to closure L: surjectivity follows from this image equality, and injectivity follows from lift_injective. Hence D ≃ closure L_H. The second closure specialization is a written argument here, not an added native declaration.")),
                Paragraph(Text("The supplier's X and the adopted owner's X are distinct nominal types. Identify them by c_b ↦ c_b, p_(s,b) ↦ p_(s,b) and f_(b,g) ↦ f_(b,g). Its inverse is the reverse constructor map; their action and encoding formulas agree in every constructor case. Conjugation therefore gives a monoid isomorphism between their full equivariant-map monoids, preserving every lazyMap(S,p) and every bijection. It carries both generated closures onto the corresponding owner closures. Compose this isomorphism with the preceding actual-domain bijections and apply Nat.card_congr. The results are exactly Nat.card(closure(U ∪ L_H)) = 59712 and Nat.card(closure L_H) = 4007 for actual functions on all 16 configurations."))
            )),
            new DocumentBlock.Section(H("Native boundary and bounded attribution"), Blocks(
                Paragraph(Text("The public supplement uses Lean 4.33.0 and Mathlib db584cd6d46c92f209a44c0f1c829460d327499d. This repository uses Lean 4.35.0 and Mathlib 56a005855ea17e0b0958f73ec801ae140b0a1679. The published proof text and its archived audit, which lists propext, Classical.choice and Quot.sound, are evidence about that supplier version; they are not a current-pin compilation of either exact End(Q) count. The current native owners supply the representation, invariant, factorization and mixed actual-domain membership theorem. Neither count is retained as a new Lean declaration by this exposition.")),
                Paragraph(Text("For 59712, current exact native evidence must additionally cover the reverse table identity, the disjoint partition, the finite counts and the restriction of the actual-domain equivalence. For 4007, the current owners do not adopt the ParentCertificate and EdgeCertificate premises, generator coverage, root and reflection applications from the supplier. In particular all 63 block proofs on the exact data, together with the supplier-to-owner and lazy-only actual-domain transports, are not current native count evidence here. Source availability does not admit a positive enumeration or an incompatible dependency. This exposition supplies the complete source-backed deduction while keeping those native obligations explicit.")),
                Paragraph(Text("The attribution is bounded to the pinned v1.1.0 software and the structural results already adopted in KleinFourInvariant, KleinFourFactorization and LazyInvertibleGeneration. The present arithmetic explanation and written transports make the source result readable in the existing local-rule vocabulary; they make no priority claim. Shortest words, relative rank, maximal submonoids and claims from other versions are outside this exposition."))
            ))), []));

    private static Formula Call(string name, params Formula[] args) =>
        new Formula.Apply(F.Id(name), [.. args]);
    private static Formula Eq(Formula a, Formula b) =>
        new Formula.Relation(a, FormulaRelationOperator.Equal, b);
    private static Formula Mem(Formula a, Formula b) =>
        new Formula.Relation(a, FormulaRelationOperator.MemberOf, b);
    private static Formula And(Formula a, Formula b) =>
        new Formula.Logic(a, FormulaLogicOperator.And, b);
    private static Formula Image(Formula set) => Seq(F.Id("T"), OpenBracket, set, CloseBracket);
    private static Formula W(Formula n) => new Formula.Subscript(F.Id("W"), n);
    private static Formula Statement()
    {
        Formula b = F.Id("b"), x = F.Id("x");
        Formula wb = new Formula.Subscript(F.Id("w"), b);
        Formula merge = Seq(Exists, Sp, b, Sp, InMacro, Sp, F.Id("Bool"), Comma, Sp,
            And(Eq(Image(W(D(1))), W(wb)), Eq(Image(W(D(3))), W(wb))));
        Formula witness = Seq(Exists, Sp, x, Sp, InMacro, Sp, new Formula.Power(F.Id("Bool"), F.Id("H")),
            Comma, Sp, b, Sp, InMacro, Sp, F.Id("Bool"), Comma, Sp,
            And(Eq(Seq(Bar, Call("O", x), Bar), D(2)),
                Eq(Image(Seq(F.Id("C"), Sp, Cup, Sp, Call("O", x))),
                    Seq(OpenBrace, new Formula.Subscript(F.Id("c"), b), CloseBrace))));
        return Seq(Forall, Sp, F.Id("T"), Sp, InMacro, Sp,
            Call("End", new Formula.Power(F.Id("Bool"), F.Id("H"))), Comma, Sp,
            Call("IsCA", F.Id("T")), Sp, Implies, Sp, Open,
            new Formula.Logic(Mem(F.Id("T"), Call("closure", Seq(F.Id("U"), Sp, Cup, Sp, F.Id("L")))),
                FormulaLogicOperator.Iff, Seq(Open,
                    new Formula.Logic(Seq(Open, merge, Close), FormulaLogicOperator.Implies, witness), Close)), Close);
    }
}
